// ------------------------------------------------------------------ yerlesim
const LANES = [810, 1110];
const AISLE = 650, STRIP = 940, EXIT_B = 905;
const SPOTS = [];
[310, 420, 530, 640, 750, 860, 970, 1080].forEach(x => SPOTS.push({ x, y: 1030 }));
[365, 475, 585, 695, 805, 915].forEach(x => SPOTS.push({ x, y: 985 }));
const SPAWN = { x: -90, y: 985 };
const nearestLane = x => LANES.reduce((a, b) => Math.abs(b - x) < Math.abs(a - x) ? b : a);
function seatExit(i) { const d = DESKS[i]; return { x: d.x, y: d.row === 0 ? AISLE : EXIT_B }; }
function routeToStrip(x, y) {
  const p = [];
  if (y < 700) { const l = nearestLane(x); if (Math.abs(x - l) > 2) p.push([l, AISLE]); p.push([l, STRIP]); }
  else if (y < 925) p.push([x, STRIP]);
  return p;
}
function routeFromStrip(tg) {
  if (tg.type === 'spot') return [[SPOTS[tg.spot].x, SPOTS[tg.spot].y]];
  if (tg.type === 'out') return [[SPAWN.x, SPAWN.y]];
  if (tg.type === 'visit') { const v = DESKS[tg.desk]; if (v.row === 1) return [[v.x + 74, STRIP], [v.x + 74, EXIT_B]]; const vl = nearestLane(v.x); return [[vl, STRIP], [vl, AISLE], [v.x + 74, AISLE]]; }
  const d = DESKS[tg.desk];
  if (d.row === 1) return [[d.x, STRIP], [d.x, EXIT_B]];
  const l = nearestLane(d.x);
  return [[l, STRIP], [l, AISLE], [d.x, AISLE]];
}
function buildPath(x, y, tg) {
  const raw = routeToStrip(x, y).concat(routeFromStrip(tg));
  const out = []; let cx = x, cy = y;
  for (const p of raw) { if (Math.hypot(p[0] - cx, p[1] - cy) > 1) { out.push(p); cx = p[0]; cy = p[1]; } }
  return out;
}

