    ids.add(t.id);
    let ch = C[t.id];
    if (!ch) { ch = C[t.id] = newChar(t); created.push(ch); }
    ch.name = t.ad; ch.balon = t.balon; ch.uzun = t.uzun || t.balon; ch.ds = t.durum; ch.nokta = t.nokta; ch.yas = t.yas;
    const np = presetFor(t.ad);
    if (ch.pre !== np) { ch.pre = np; if (ch.fig) { const old = ch.loc; makeFig(ch); setCoffeePose(ch, old === 'coffee'); } }
    if (ch.desk !== t.koltuk) {
      if (deskOwner[ch.desk] === ch) { deskOwner[ch.desk] = null; DESKS[ch.desk].sig = null; }
      ch.desk = t.koltuk;
      if (!created.includes(ch) && ch.loc === 'seat') { const d = DESKS[ch.desk]; ch.x = d.x; ch.y = d.y; }
    }
    deskOwner[ch.desk] = ch;
