  let order = false;
  for (const ch of all) {
    if (ch.loc === 'visit' && performance.now() > ch.visitUntil) { const tg = wantOf(ch) === 'coffee' ? { type: 'spot', spot: ch.spot } : { type: 'seat', desk: ch.desk }; startWalk(ch, tg); }
    if (ch.loc === 'walk' && ch.fig) {
      let rem = 260 * dt;
      while (rem > 0 && ch.path.length) {
        const p = ch.path[0], dx = p[0] - ch.x, dy = p[1] - ch.y, dist = Math.hypot(dx, dy);
        if (dist <= rem) { ch.x = p[0]; ch.y = p[1]; rem -= dist; ch.path.shift(); }
        else { ch.x += dx / dist * rem; ch.y += dy / dist * rem; rem = 0; }
      }
      const ph = t * 9.5 + ch.ph, sw = Math.sin(ph);
      if (ch.legL) {
        ch.legL.setAttribute('transform', `rotate(${(sw * 24).toFixed(1)} -14 14)`);
        ch.legR.setAttribute('transform', `rotate(${(-sw * 24).toFixed(1)} 14 14)`);
        ch.armL.setAttribute('transform', `rotate(${(-sw * 20).toFixed(1)} -34 -46)`);
        ch.armRw.setAttribute('transform', `rotate(${(sw * 20).toFixed(1)} 34 -46)`);
        ch.bob.setAttribute('transform', `translate(0,${(-Math.abs(sw) * 4).toFixed(1)})`);
      } else if (ch.rb) {
        ch.rb.setAttribute('transform', `translate(0,${(-2 - Math.abs(sw) * 4).toFixed(1)}) rotate(${(sw * 3).toFixed(1)} 0 0)`);
      }
      placeFig(ch);
      if (!ch.path.length) arrive(ch);
    }
    if (ch.fig) order = true;
  }
  if (order) {
    const figs = all.filter(c => c.fig).sort((a, b) => a.y - b.y);
    for (let i = 0; i < figs.length; i++) if (walkersG.children[i] !== figs[i].fig) walkersG.appendChild(figs[i].fig);
  }
  updateUI(all);
  stepFx(t);
