// ------------------------------------------------------------------ hud
function hud(data) {
  const n = data.sayilar || {};
  const items = [['calisiyor', T('ofis.hud_working', 'Çalışıyor'), 1462, 102], ['bekliyor', T('ofis.hud_waiting', 'Seni bekliyor'), 1612, 102], ['bosta', T('ofis.hud_idle', 'Boşta'), 1772, 102], ['belirsiz', T('ofis.hud_unknown', 'Bilinmiyor'), 1462, 138], ['gecmis', T('ofis.hud_past', 'Geçmiş'), 1612, 138], ['toplam', T('ofis.hud_chats', 'Sohbet'), 1772, 138]];
  n.toplam = (data.sekmeler || []).length + (data.digerleri || 0);
  if (data.baslik) $('ekipad').textContent = data.baslik;
  let s = '';
  for (const [k, lab, x, y] of items)
    s += `<circle cx="${x}" cy="${y - 7}" r="7" fill="${COL[k] || '#9aa3c7'}" stroke="#fff" stroke-width="2"/><text x="${x + 14}" y="${y}" font-size="16" font-weight="700" fill="#fff">${lab} ${n[k] || 0}</text>`;
  $('durumkutu').innerHTML = s;
  panoCiz(data.pano);
  LIMIT = data.limit || null; limitCiz();
  const kb = data.kumbara && data.kumbara.kalan;
  const kt = $('kumbara_t'); if (kt) kt.textContent = (kb === null || kb === undefined) ? '$---' : '$' + Math.floor(kb);
}
let LIMIT = null;
let limitFloor = 1052; // lowest the box may reach: above the window's office tabs (set by fitRoom)
function limitCiz() {
  const g = $('limitkutu');
  const pen = LIMIT && Array.isArray(LIMIT.pencereler) ? LIMIT.pencereler : [];
  if (!pen.length) { g.innerHTML = ''; return; }
  const W = 330, H = 30 + pen.length * 40 + 22, X = 1394, Y = Math.max(560, Math.min(922, limitFloor - H));
  let h = `<rect x="${X}" y="${Y}" width="${W}" height="${H}" rx="14" fill="#2a2850" stroke="#ffd36b" stroke-width="2.5" opacity=".95"/>` +
    `<text x="${X + 16}" y="${Y + 22}" font-size="15" font-weight="800" fill="#ffd36b" letter-spacing="2">${esc(buyuk(T('ofis.limit', 'Limit')))}</text>`;
  const now = Date.now();
  pen.forEach((p, i) => {
    const y = Y + 30 + i * 40;
    let yz = Math.max(0, Math.min(100, Number(p.yuzde) || 0));
    const tBit = Date.parse(p.sifirlanma); const bitti = !isNaN(tBit) && tBit <= now; if (bitti) yz = 0;
    const renk = yz >= 85 ? '#ef4b4b' : (yz >= 60 ? '#ffc93c' : '#4cc38a');
    let sf = '';
    const t = Date.parse(p.sifirlanma);
    if (!isNaN(t)) {
      const sn = Math.max(0, Math.floor((t - now) / 1000));
      const gun = Math.floor(sn / 86400), sa = Math.floor((sn % 86400) / 3600), dk = Math.floor((sn % 3600) / 60);
      sf = bitti ? T('ofis.limit_renewed', 'yenilendi, yeni ölçüm bekleniyor') : T('ofis.limit_resets_in', 'sıfırlanma: {sure}').replace('{sure}', sure(gun, sa, dk, sn));
    }
    h += `<text x="${X + 16}" y="${y + 12}" font-size="14" font-weight="700" fill="#fff">${esc(p.ad)}</text>` +
      `<text x="${X + W - 16}" y="${y + 12}" font-size="13" fill="#cfd0ee" text-anchor="end">${esc(sf)}</text>` +
      `<rect x="${X + 16}" y="${y + 18}" width="${W - 90}" height="12" rx="6" fill="#14122e" stroke="#fff" stroke-opacity=".25" stroke-width="1.5"/>` +
      `<rect x="${X + 16}" y="${y + 18}" width="${Math.max(yz > 0 ? 8 : 0, (W - 90) * yz / 100)}" height="12" rx="6" fill="${renk}"/>` +
      `<text x="${X + W - 16}" y="${y + 29}" font-size="15" font-weight="800" fill="${renk}" text-anchor="end">${bitti ? '' : yuzde(yz)}</text>`;
  });
  let alt = '';
  const gt = Date.parse(LIMIT.guncelleme);
  if (!isNaN(gt)) {
    const d = new Date(gt);
    alt = T('ofis.limit_updated', 'son güncelleme: {saat}').replace('{saat}', saatYaz(d));
    if (now - gt > 30 * 60000) alt += ' ' + T('ofis.limit_stale', '(eski)');
  }
  h += `<text x="${X + 16}" y="${Y + H - 8}" font-size="12" fill="#fff" opacity=".5">${esc(alt)}</text>`;
  g.innerHTML = h;
}
let clockT = 0;
function clock() {
  const d = new Date();
  $('saat_h').setAttribute('transform', `rotate(${((d.getHours() % 12) + d.getMinutes() / 60) * 30} 1790 236)`);
  $('saat_m').setAttribute('transform', `rotate(${d.getMinutes() * 6} 1790 236)`);
}

// ------------------------------------------------------------------ veri cekme
let failCount = 0, surum0 = null, polling = false;
function poll() {
  return;
  if (polling) return;
  polling = true;
  const ac = new AbortController();
  const to = setTimeout(() => ac.abort(), 3000);
  fetch('/durum', { cache: 'no-store', signal: ac.signal }).then(r => r.json()).then(d => {
    failCount = 0; $('baglanti').setAttribute('visibility', 'hidden');
    if (d.surum) {
      if (surum0 === null) surum0 = d.surum;
      else if (d.surum !== surum0) { location.reload(); return; }
    }
    apply(d);
  }).catch(() => { if (++failCount >= 2) $('baglanti').setAttribute('visibility', 'visible'); })
    .finally(() => { clearTimeout(to); polling = false; });
}

