const DEMO_NAMES = ['Karakterler', 'Kız Kulesi', 'Silahlar', 'Yönetici', 'Test ve Paket', 'Sesler', 'Beceriler', 'Bilgisayar Rakibi', 'Yeni Harita', 'Temizlik', 'Ad Araştırması', 'Kredi İşçisi'];
